 "content": "def transform(grid):
    """Connect matching tile-center colors through the blank separators."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    def runs(n, is_active):
        result = []
        i = 0
        while i < n:
            if not is_active(i):
                i += 1
                continue
            start = i
            while i < n and is_active(i):
                i += 1
            result.append((start, i - 1))
        return result

    row_blocks = runs(h, lambda r: any(v != 0 for v in grid[r]))
    col_blocks = runs(w, lambda c: any(grid[r][c] != 0 for r in range(h)))
    # Ignore clipped fragments at the far edge; they are not complete tiles.
    row_blocks = [(a, b) for a, b in row_blocks if b - a + 1 >= 3]
    col_blocks = [(a, b) for a, b in col_blocks if b - a + 1 >= 3]
    row_centers = [(a + b) // 2 for a, b in row_blocks]
    col_centers = [(a + b) // 2 for a, b in col_blocks]

    values = [[grid[r][c] for c in col_centers] for r in row_centers]

    # For any repeated center color in a common tile row, extend it through
    # each intervening blank column gap, without changing tile contents.
    for ri, r in enumerate(row_centers):
        for c1 in range(len(col_centers)):
            color = values[ri][c1]
            if color == 0:
                continue
            for c2 in range(c1 + 1, len(col_centers)):
                if values[ri][c2] == color:
                    for j in range(c1, c2):
                        for c in range(col_blocks[j][1] + 1, col_blocks[j + 1][0]):
                            if grid[r][c] == 0:
                                out[r][c] = color

    # Same operation vertically.
    for ci, c in enumerate(col_centers):
        for r1 in range(len(row_centers)):
            color = values[r1][ci]
            if color == 0:
                continue
            for r2 in range(r1 + 1, len(row_centers)):
                if values[r2][ci] == color:
                    for j in range(r1, r2):
                        for r in range(row_blocks[j][1] + 1, row_blocks[j + 1][0]):
                            if grid[r][c] == 0:
                                out[r][c] = color
    return out

if __name__ == '__main__':
    pass
