 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate framed square tiles: uniform nonzero perimeter with a different
    # color at its center. The repeated tile scale is selected by prevalence.
    candidates = {}
    for size in range(3, min(h, w, 15) + 1, 2):
        rad = size // 2
        found = []
        for r in range(rad, h - rad):
            for c in range(rad, w - rad):
                border = set()
                for dc in range(-rad, rad + 1):
                    border.add(grid[r - rad][c + dc])
                    border.add(grid[r + rad][c + dc])
                for dr in range(-rad + 1, rad):
                    border.add(grid[r + dr][c - rad])
                    border.add(grid[r + dr][c + rad])
                if len(border) == 1:
                    frame = next(iter(border))
                    if frame != 0 and grid[r][c] != frame:
                        found.append((r, c, grid[r][c]))
        candidates[size] = found

    size = max(candidates, key=lambda s: len(candidates[s]))
    tiles = candidates[size]
    if not tiles:
        return out
    rad = size // 2

    # Keep only candidates on the dominant regular lattice (guards against
    # incidental framed patterns inside tile contents).
    row_centers = sorted(set(r for r, _, _ in tiles))
    col_centers = sorted(set(c for _, c, _ in tiles))
    values = {(r, c): v for r, c, v in tiles}
    counts = Counter(v for _, _, v in tiles)
    background = counts.most_common(1)[0][0]

    # Between matching non-background tile centers, draw through blank gaps;
    # preserve the contents and frames of all intervening tiles.
    for r in row_centers:
        cols = [c for c in col_centers if (r, c) in values]
        for i, c1 in enumerate(cols):
            color = values[(r, c1)]
            if color == background:
                continue
            for j in range(i + 1, len(cols)):
                c2 = cols[j]
                if values[(r, c2)] == color:
                    for k in range(i, j):
                        left, right = cols[k] + rad + 1, cols[k + 1] - rad
                        for c in range(left, right):
                            if grid[r][c] == 0:
                                out[r][c] = color

    for c in col_centers:
        rows = [r for r in row_centers if (r, c) in values]
        for i, r1 in enumerate(rows):
            color = values[(r1, c)]
            if color == background:
                continue
            for j in range(i + 1, len(rows)):
                r2 = rows[j]
                if values[(r2, c)] == color:
                    for k in range(i, j):
                        top, bottom = rows[k] + rad + 1, rows[k + 1] - rad
                        for r in range(top, bottom):
                            if grid[r][c] == 0:
                                out[r][c] = color
    return out


if __name__ == '__main__':
    pass
