    # for even-sized tiles. The current lattice may have tile size 5, 4, etc.
    tiles = []
    for ra, rb in row_runs:
        for ca, cb in col_runs:
            if rb - ra != cb - ca:
                continue
            size = rb - ra + 1
            if size % 2:
                rs = [ra + size // 2]
                cs = [ca + size // 2]
            else:
                rs = [ra + size // 2 - 1, ra + size // 2]
                cs = [ca + size // 2 - 1, ca + size // 2]
            vals = [grid[r][c] for r in rs for c in cs]
            if len(set(vals)) == 1 and vals[0] != 0:
                tiles.append((rs, cs, vals[0]))
