        return out

    # Group the tile centers into lattice rows/columns and detect the colors
    # that mark repeated objects rather than the common interior fill.
    tile_rows = {}
    tile_cols = {}
    for rs, cs, color in tiles:
        rc = sum(rs) // len(rs)
        cc = sum(cs) // len(cs)
        tile_rows.setdefault(rc, []).append((cc, color, rs, cs))
        tile_cols.setdefault(cc, []).append((rc, color, rs, cs))

    from collections import Counter
    freq = Counter(color for _, _, color in tiles)
    common = freq.most_common(1)[0][0]
    markers = {c for c, n in freq.items() if c != common}

    # Extend identical markers between neighboring matching tiles. In the
