    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def runs(n, active):
        result = []
        i = 0
        while i < n:
            if not active(i):
                i += 1
                continue
            start = i
            while i < n and active(i):
                i += 1
            result.append((start, i - 1))
        return result

    row_runs = runs(h, lambda r: any(grid[r][c] != 0 for c in range(w)))
    col_runs = runs(w, lambda c: any(grid[r][c] != 0 for r in range(h)))
    # Ignore isolated border fragments and infer nominal repeating tile size.
    row_runs = [x for x in row_runs if x[1] - x[0] + 1 >= 3]
    col_runs = [x for x in col_runs if x[1] - x[0] + 1 >= 3]
    if not row_runs or not col_runs:
        return out
    row_size = Counter(b - a + 1 for a, b in row_runs).most_common(1)[0][0]
    col_size = Counter(b - a + 1 for a, b in col_runs).most_common(1)[0][0]
    size = min(row_size, col_size)

    # Keep only tile-sized active bands, allowing a clipped edge tile.
    row_runs = [x for x in row_runs if x[1] - x[0] + 1 >= size - 1]
    col_runs = [x for x in col_runs if x[1] - x[0] + 1 >= size - 1]
    if not row_runs or not col_runs:
        return out

    def central_coords(a, b, nominal):
        if nominal % 2:
            wanted = [a + nominal // 2]
        else:
            wanted = [a + nominal // 2 - 1, a + nominal // 2]
        return [p for p in wanted if a <= p <= b]

    row_centers = [central_coords(a, b, row_size) for a, b in row_runs]
    col_centers = [central_coords(a, b, col_size) for a, b in col_runs]

    # Extract the interior/center color of every repeated tile block.
    values = []
    for (ra, rb), rcs in zip(row_runs, row_centers):
        row_values = []
        for (ca, cb), ccs in zip(col_runs, col_centers):
            center_vals = [grid[r][c] for r in rcs for c in ccs if grid[r][c] != 0]
            if center_vals:
                row_values.append(Counter(center_vals).most_common(1)[0][0])
            else:
                row_values.append(0)
        values.append(row_values)

    frequencies = Counter(v for row in values for v in row if v != 0)
    if not frequencies:
        return out
    common = frequencies.most_common(1)[0][0]
    markers = {v for v, count in frequencies.items() if v != common and count < frequencies[common]}

    # Connect matching marker tiles, across gutters only. Never repaint the
    # intervening tiles; each gap receives a line across the tile-center rows.
    for ri, rcs in enumerate(row_centers):
        for color in markers:
            positions = [ci for ci, value in enumerate(values[ri]) if value == color]
